import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"RAG 与 Agent","description":"","frontmatter":{},"headers":[],"relativePath":"llm/rag-agent.md","filePath":"llm/rag-agent.md","lastUpdated":null}'),n={name:"llm/rag-agent.md"};function r(o,l,h,u,g,s){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="rag-与-agent" tabindex="-1">RAG 与 Agent <a class="header-anchor" href="#rag-与-agent" aria-label="Permalink to &quot;RAG 与 Agent&quot;">​</a></h1><p>一句话：RAG 让模型先查资料再回答，Agent 让模型根据目标规划步骤并调用工具。</p><h2 id="rag-是什么" tabindex="-1">RAG 是什么 <a class="header-anchor" href="#rag-是什么" aria-label="Permalink to &quot;RAG 是什么&quot;">​</a></h2><p>RAG 是 Retrieval-Augmented Generation，检索增强生成。</p><p>典型流程：</p><ol><li>把文档切分成片段。</li><li>用 Embedding 建立语义索引。</li><li>用户提问时检索相关片段。</li><li>把片段放进上下文。</li><li>模型基于资料回答。</li></ol><p>RAG 的核心不是“把所有文档塞给模型”，而是把最相关、可信、足够短的材料放进上下文。</p><h2 id="rag-适合什么" tabindex="-1">RAG 适合什么 <a class="header-anchor" href="#rag-适合什么" aria-label="Permalink to &quot;RAG 适合什么&quot;">​</a></h2><p>适合：</p><ul><li>企业知识库问答。</li><li>产品文档助手。</li><li>法规、制度、手册查询。</li><li>需要引用来源的总结。</li><li>资料经常更新的场景。</li></ul><p>不适合：</p><ul><li>没有可靠原始资料的问题。</li><li>需要复杂事务操作但没有工具接口的问题。</li><li>文档本身质量很差、互相矛盾的问题。</li></ul><h2 id="rag-常见失败点" tabindex="-1">RAG 常见失败点 <a class="header-anchor" href="#rag-常见失败点" aria-label="Permalink to &quot;RAG 常见失败点&quot;">​</a></h2><ul><li>文档切分太碎，答案缺上下文。</li><li>检索召回不准，相关资料没找到。</li><li>塞入太多无关片段，模型抓不住重点。</li><li>没有来源标记，无法复查。</li><li>文档版本混乱，新旧规则混在一起。</li></ul><h2 id="agent-是什么" tabindex="-1">Agent 是什么 <a class="header-anchor" href="#agent-是什么" aria-label="Permalink to &quot;Agent 是什么&quot;">​</a></h2><p>Agent 通常指模型不只是回答，而是围绕目标执行一组动作。</p><p>它可能会：</p><ul><li>拆解任务。</li><li>选择工具。</li><li>查询网页或数据库。</li><li>写文件或运行代码。</li><li>根据结果调整下一步。</li></ul><p>Agent 的关键不是“像人一样自主”，而是让模型在受控边界内调用工具完成任务。</p><h2 id="tool-use-和-function-calling" tabindex="-1">Tool Use 和 Function Calling <a class="header-anchor" href="#tool-use-和-function-calling" aria-label="Permalink to &quot;Tool Use 和 Function Calling&quot;">​</a></h2><p>Tool Use 是模型使用外部工具的能力。Function Calling 是常见接口形式：模型输出结构化参数，由程序调用实际函数。</p><p>这样可以把模型不擅长的部分交给工具：</p><ul><li>查实时数据。</li><li>运行计算。</li><li>读写数据库。</li><li>调用业务系统。</li><li>验证文件和代码。</li></ul><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li>工具权限要最小化。</li><li>重要动作要有确认或审计。</li><li>工具输入输出要结构化。</li><li>不要让模型凭空假设工具结果。</li><li>对失败路径和重试次数做限制。</li></ul><h2 id="rag-和-agent-的关系" tabindex="-1">RAG 和 Agent 的关系 <a class="header-anchor" href="#rag-和-agent-的关系" aria-label="Permalink to &quot;RAG 和 Agent 的关系&quot;">​</a></h2><p>RAG 可以是 Agent 的一个工具。Agent 也可以先检索，再总结，再调用其他工具。</p><p>简单区分：</p><ul><li>RAG 重点是“查资料后回答”。</li><li>Agent 重点是“规划和执行动作”。</li><li>Workflow 重点是“固定流程自动化”。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/prompting/basics">Prompt 入门</a>，学习任务、上下文、约束和工具参数的表达方式。</li><li>阅读 <a href="/tools/common-tools">常用工具</a>，比较 Web、API、本地模型、RAG 与 Agent 工具的适用场景。</li></ul>',31)])])}const c=a(n,[["render",r]]);export{p as __pageData,c as default};
